<?php
require dirname(__DIR__) . '/includes/bootstrap.php'; require_role('admin');
$where='1=1'; $params=[]; if (get('q')!=='') { $where='(a.action LIKE ? OR a.details LIKE ? OR u.name LIKE ?)'; $params=array_fill(0,3,'%' . get('q') . '%'); }
$join=' FROM activity_logs a LEFT JOIN users u ON u.id=a.user_id WHERE ' . $where;
$total=(int)scalar('SELECT COUNT(*)' . $join,$params);
$activities=rows('SELECT a.*,u.name' . $join . ' ORDER BY a.id DESC LIMIT 20 OFFSET ' . ((page_number()-1)*20),$params);
$title='Activity & reports'; require ROOT . '/includes/dashboard-start.php';
?>
<h2>Availability by university</h2><div class="table-responsive panel table-panel"><table class="table"><thead><tr><th>University</th><th>Public listings</th><th>Available slots</th><th>Fully occupied</th></tr></thead><tbody><?php foreach (rows('SELECT u.name,COUNT(d.id) listings,COALESCE(SUM(d.available_slots),0) slots,COALESCE(SUM(d.available_slots=0),0) full FROM universities u LEFT JOIN dormitories d ON d.university_id=u.id AND ' . public_condition() . ' GROUP BY u.id,u.name ORDER BY u.name') as $r): ?><tr><td><?= e($r['name']) ?></td><td><?= $r['listings'] ?></td><td><?= $r['slots'] ?></td><td><?= $r['full'] ?></td></tr><?php endforeach; ?></tbody></table></div><h2 class="mt-4">User activity</h2><form class="inline-filter" method="get"><?php field('Search activity or user','q',get('q'),'search'); ?><button class="btn btn-primary">Search</button></form><div class="table-responsive panel table-panel"><table class="table"><thead><tr><th>Time (PHT)</th><th>User</th><th>Action</th><th>Details</th></tr></thead><tbody><?php foreach ($activities as $a): ?><tr><td><?= e($a['created_at']) ?></td><td><?= e($a['name'] ?? 'System') ?></td><td><?= e($a['action']) ?></td><td><?= e($a['details']) ?></td></tr><?php endforeach; ?><?php if (!$activities): ?><tr><td colspan="4">No matching activity.</td></tr><?php endif; ?></tbody></table></div><?php paginate($total,20); require ROOT . '/includes/dashboard-end.php'; ?>
